/* Lightweight local Chart-compatible canvas renderer for line/bar report charts. */
(function(g){'use strict';function Chart(ctx,cfg){this.ctx=ctx&&ctx.canvas?ctx:ctx.getContext('2d');this.canvas=this.ctx.canvas;this.config=cfg||{};this.draw();}Chart.prototype.draw=function(){var c=this.canvas,x=this.ctx,d=(this.config.data||{}),labels=d.labels||[],sets=d.datasets||[];c.width=c.clientWidth||700;c.height=c.clientHeight||280;x.clearRect(0,0,c.width,c.height);var pad=36,w=c.width-pad*2,h=c.height-pad*2;var vals=[];sets.forEach(function(s){(s.data||[]).forEach(function(v){vals.push(Number(v)||0);});});var max=Math.max(1,Math.max.apply(null,vals));x.strokeStyle='#cbd5e1';x.fillStyle='#64748b';x.font='11px sans-serif';x.beginPath();x.moveTo(pad,pad);x.lineTo(pad,pad+h);x.lineTo(pad+w,pad+h);x.stroke();if(!labels.length)return;sets.forEach(function(s,si){var data=s.data||[];x.strokeStyle=s.borderColor||'#0f766e';x.fillStyle=s.backgroundColor||'rgba(15,118,110,.2)';x.beginPath();data.forEach(function(v,i){var px=pad+(labels.length===1?w/2:(i*w/(labels.length-1))),py=pad+h-(Number(v)||0)/max*h;if((cfg&&cfg.type)==='bar'){var bw=Math.max(6,w/Math.max(labels.length,1)*.5);x.fillRect(px-bw/2,py,bw,pad+h-py);}else{if(i===0)x.moveTo(px,py);else x.lineTo(px,py);}});if((cfg&&cfg.type)!=='bar')x.stroke();});labels.forEach(function(l,i){var px=pad+(labels.length===1?w/2:(i*w/(labels.length-1)));x.fillText(String(l).slice(0,12),px-14,c.height-8);});};Chart.prototype.destroy=function(){};g.Chart=Chart;})(window);
